export function slugify(input: string): string {
  return input
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, "-")
    .replace(/^-+|-+$/gu, "");
}

type SlugOptions = { separator: string; maxLength: number };

const DEFAULT_OPTIONS: SlugOptions = { separator: "-", maxLength: 96 };

function truncate(value: string, limit: number): string {
  if (value.length <= limit) {
    return value;
  }
  return value.slice(0, limit).replace(/-+$/u, "");
}

function withSeparator(value: string, separator: string): string {
  return value.split("-").join(separator);
}

function normalizeOptions(given: Partial<SlugOptions>): SlugOptions {
  return { ...DEFAULT_OPTIONS, ...given };
}
